import { z } from "zod";
import { Face, MediaOwner } from "@/contract/domain";
import raw from "./faces.json";
import { PHOTOS } from "./photos";

// Wallspace inventory for the Atlanta demo (generated by src/data/gen/build-faces.mjs; ids are stable).
// location "real": an OpenStreetMap advertising=billboard node inside the City of Atlanta (c) OpenStreetMap contributors, ODbL.
//   Its position is real. Its kind (OSM tags animated/description else bulletin), lit (OSM tag else false), size, read side, facing,
//   rate and owner assignment are sample values: OSM carries none of them.
// location "sample": a face we added in a neighbourhood OSM does not cover, on a real street centreline. Everything is sample.
// Every monthly rate is a sample rate; there is no pricing in the product.
// Neighbourhood: the City of Atlanta Department of City Planning layer by point-in-polygon, except two colloquial districts the
// layer lacks (Little Five Points, East Atlanta Village: circles of 500 m and 600 m) and Buckhead, which merges the layer's
// "Buckhead Village" and "Buckhead Forest" polygons.

export const faces: Face[] = z.array(Face).parse(raw).map((f) => (PHOTOS[f.id] ? { ...f, photoUrl: PHOTOS[f.id].photoUrl, photoCredit: PHOTOS[f.id].photoCredit } : f));

export const owners: MediaOwner[] = z.array(MediaOwner).parse([
  { id: "own-peachline", name: "Peachline Outdoor (sample)", sample: true },
  { id: "own-southside", name: "Southside Signs (sample)", sample: true },
  // Names below come from the OSM operator tag; sample=false covers the name only, the inventory attached to them is sample.
  { id: "own-taz", name: "Taz Anderson Media Group", sample: false },
  { id: "own-lamar", name: "Lamar Advertising", sample: false },
  { id: "own-delta", name: "Delta Air Lines", sample: false },
]);

export const OSM_ATTRIBUTION = "Billboard positions (c) OpenStreetMap contributors, ODbL. Neighbourhoods: City of Atlanta Department of City Planning.";

const byId = new Map(faces.map((f) => [f.id, f]));
export function faceById(id: string): Face | undefined {
  return byId.get(id);
}
export const neighbourhoodsWithFaces = [...new Set(faces.map((f) => f.neighbourhood))].sort();
